 FROM telemetry_resolutions WHERE key_id=OLD.key_id AND project_id=OLD.project_id AND session_id=OLD.session_id AND parent_session_id IS NOT NULL
 ORDER BY matched_by,reported_at DESC,started_at DESC,trace_id DESC,span_id DESC LIMIT 1; END;

